'use strict';
const AR=LoganAliyunRetrieval;
let aliDraft=null,aliDraftKey='',aliOrigin=null;
function aliRemember(){state.aliyunDrafts=state.aliyunDrafts||{};state.aliyunDrafts[aliDraftKey]=JSON.parse(JSON.stringify(aliDraft));return save();}
function aliPatch(key,value){aliDraft[key]=value;aliRemember();}
function aliType(value){aliDraft.targetType=value;aliDraft.targetValue='';aliDraft.bindingConfirmed=false;aliDraft.source='用户填写';aliRemember();aliShow();}
startAcquisitionFromWorkspace=function(id){const i=id?state.issues.find(x=>x.id===id):null;aliDraftKey=id||'global';aliOrigin=id&&['workbench','logcenter'].includes(page)?page:null;aliDraft=JSON.parse(JSON.stringify(state.aliyunDrafts?.[aliDraftKey]||AR.draft(i)));aliDraft.step=1;aliShow();};
deskStartCollection=function(){startAcquisitionFromWorkspace(issue().id);};
collectForm=function(){startAcquisitionFromWorkspace(issue().id);};
const aliHints={device:'从 Debug 日志 NativePushAliyun 中复制 deviceId。不要用普通业务设备 ID 替代。',account:'填写已在 Android 测试应用中绑定成功的业务 userId。',alias:'填写已绑定成功的手机号，作为别名寻址；不是短信发送。'};
function aliStep(step){try{if(step>1)AR.validate(aliDraft,step===3);aliDraft.step=step;aliRemember();aliShow();}catch(e){$('#ali-error').textContent=e.message;}}
function aliShow(){const d=aliDraft,i=state.issues.find(x=>x.id===d.issueId),step=d.step;let body='';
 if(step===1)body=`<p>从工单带入已保存的阿里云参数，或手动填写推送目标。</p><label for="ali-app">应用</label><select id="ali-app" onchange="aliPatch('app',this.value)"><option value="com.hxl.xlb.test">Android 测试应用 · com.hxl.xlb.test</option></select><label for="ali-type">推送目标类型</label><select id="ali-type" onchange="aliType(this.value)">${Object.entries(AR.labels).map(([v,l])=>`<option value="${v}" ${v===d.targetType?'selected':''}>${l}</option>`).join('')}<option disabled>标签 · 当前未绑定，暂不使用</option></select><label for="ali-target">${d.targetType==='device'?'阿里云 deviceId':d.targetType==='account'?'业务 userId':'已绑定的手机号（别名）'}</label><input id="ali-target" autocomplete="off" value="${esc(d.targetValue)}" placeholder="${d.targetType==='device'?'填写 NativePushAliyun 日志中的 deviceId':d.targetType==='account'?'填写已绑定的 userId':'填写已绑定的手机号'}" oninput="aliPatch('targetValue',this.value);aliPatch('source','用户填写')"><small>${aliHints[d.targetType]}</small>${d.targetType!=='device'?`<label class="check"><input type="checkbox" ${d.bindingConfirmed?'checked':''} onchange="aliPatch('bindingConfirmed',this.checked)">我已确认该${AR.labels[d.targetType]}在当前应用绑定成功</label><small>此为人工核对，原型没有查询阿里云绑定状态，也不推断会命中几台设备。</small>`:''}${i?`<div class="notice">来自工单 ${esc(i.id)}。${d.source==='工单保存的阿里云推送参数'?'已带入工单保存的推送参数，请复核。':'此工单没有明确的阿里云推送参数，请手动填写；不把原设备字段当作阿里云 deviceId。'}</div>`:''}`;
 else if(step===2)body=`<p><strong>${esc(AR.labels[d.targetType])}：${esc(d.targetValue)}</strong></p><p>以下信息用于记录回捞用途和关联调查；尚未映射成客户端推送指令。</p><label for="ali-title">回捞用途（可选）</label><input id="ali-title" value="${esc(d.title)}" placeholder="例如：排查登录后持续转圈" oninput="aliPatch('title',this.value)"><label for="ali-issue">关联工单（可选）</label><select id="ali-issue" onchange="aliPatch('issueId',this.value)">${captureIssueOptions(d.issueId)}</select><details><summary>故障时段（可选，作为排查线索）</summary><label for="ali-begin">开始 · 北京时间</label><input type="datetime-local" id="ali-begin" value="${esc(d.begin)}" onchange="aliPatch('begin',this.value)"><label for="ali-end">结束 · 北京时间</label><input type="datetime-local" id="ali-end" value="${esc(d.end)}" onchange="aliPatch('end',this.value)"></details><div class="notice"><strong>回捞流程已明确，具体消息协议待对接</strong><p>客户端收到推送后上传日志，平台收到后更新回捞状态。消息类型、命令字和载荷字段尚未提供，不自动生成。</p><p>通知扩展参数用于打开业务页面，需按场景确认；本次不代填，也不当作回捞命令。</p></div>`;
 else body=`<h3>核对推送参数</h3><dl class="product-facts"><dt>应用</dt><dd>${AR.app.name}</dd><dt>包名</dt><dd>${AR.app.packageName}</dd><dt>目标类型</dt><dd>${AR.labels[d.targetType]}</dd><dt>目标值</dt><dd>${esc(d.targetValue)}</dd><dt>参数来源</dt><dd>${esc(d.source)}</dd><dt>关联工单</dt><dd>${esc(d.issueId||'暂不关联')}</dd></dl><ol class="ali-chain"><li>调用阿里云推送</li><li>客户端收到推送消息</li><li>客户端上传日志</li><li>平台收到日志并更新状态</li><li>回捞成功，随后解析与阅读</li></ol><p class="notice">当前仅模拟以上状态变化，不调用阿里云、不发送消息。真实消息协议及上传结果通知方式待对接；不生成虚构指令或真实回执。</p><details><summary>本地异常演练</summary><label for="ali-scenario">演练结果</label><select id="ali-scenario" onchange="aliPatch('scenario',this.value)">${Object.entries({success:'回捞并解析成功',pushfail:'阿里云推送失败',timeout:'客户端未收到消息',empty:'客户端无日志',uploadfail:'日志上传失败',parsefail:'回捞成功但解析失败'}).map(([v,l])=>`<option value="${v}" ${d.scenario===v?'selected':''}>${l}</option>`).join('')}</select></details>`;
 openModal(aliOrigin?'补充回捞 · 阿里云推送':'日志回捞 · 阿里云推送',`<div class="capture-wizard"><ol class="capture-steps">${['填写推送参数','关联排查信息','核对并发起'].map((label,n)=>`<li class="${step===n+1?'active':''}" ${step===n+1?'aria-current="step"':''}>${n+1} ${label}</li>`).join('')}</ol><div class="capture-body">${body}<p id="ali-error" class="error" role="alert"></p></div><div class="capture-footer"><div>${btn('保存草稿','aliSaveExit()')}${btn('取消','closeModal()')}</div><div>${step>1?btn('上一步',`aliStep(${step-1})`):''}${btn(step===3?'模拟发起回捞':'下一步',step===3?'aliSubmit()':`aliStep(${step+1})`,'primary')}</div></div></div>`,true);$('#modal').classList.add('capture-dialog');
}
function aliSaveExit(){if(aliRemember()){closeModal();toast('阿里云回捞草稿已保存，未发送推送');}else $('#ali-error').textContent='存储不足，草稿未保存，请保留输入内容';}
function aliSubmit(){const backup=JSON.stringify(state);try{const r=AR.create(state,aliDraft,M);M.advance(r);delete state.aliyunDrafts?.[aliDraftKey];if(!save()){state=JSON.parse(backup);throw Error('存储不足，请保留输入，回捞请求未保存');}closeModal();workUI.collectionKey=r.product.stableKey;workUI.collectionMode='push';workUI.collectionStatus='';workUI.collectionQuery='';collectionReadId=null;if(r.issueId)state.active=r.issueId;if(aliOrigin&&r.issueId){desk.tool='collect';page=aliOrigin;render();}else go('collectioncenter');toast('已创建本地回捞演练，请查看推送与接收进度');}catch(e){$('#ali-error').textContent=e.message;}}
const aliPreviousAdvance=M.advance;
M.advance=function(r){if(!r.product?.aliyun)return aliPreviousAdvance(r);AR.advance(r,M);if(r.product.aliyun.platformReceived&&!r.product.observed){const data=collectionFixture({platform:'Native'});data.version=null;data.build=null;data.source='本地合成文件，非该推送目标的真实日志';data.records=data.records.map(({file,line,code,...x})=>({...x,scene:'generic',sourceVerified:false}));C.observe(r,data);}};
const aliPreviousCollection=inlineCollection;
inlineCollection=function(x){const r=x.request,a=r.product?.aliyun;if(!a)return aliPreviousCollection(x);const recovered=aliRecovered(r),ended=M.terminal.includes(r.status),parseStatus=recovered?'重新解析完成（原批次保留）':r.task?'解析完成':r.status==='解析失败'?'解析失败':a.platformReceived?'待解析':'等待文件';return `<section class="capture-detail-head"><span class="eyebrow">阿里云回捞 / ${r.id} · 本地演练</span><h2>${esc(r.product.title)}</h2><p>${esc(a.app.name+' · '+a.app.packageName)}</p><p>${AR.labels[a.targetType]}：${esc(a.targetValue)} · ${esc(r.issueId||'未关联工单')}</p><div class="capture-next"><strong>${esc(r.status==='已取消'&&!a.platformReceived?'已取消':a.retrievalStatus)}</strong><p>日志处理：${parseStatus}</p>${a.platformReceived?'<p>平台已收到日志，回捞成功；解析失败不会把已收到的原文件变成回捞失败。</p>':''}</div></section><section class="product-card"><h3>回捞进度</h3><ol class="ali-chain">${[['阿里云推送',a.channelReceipt?'已接受（模拟）':r.status==='推送失败'?'失败':'未接受'],['客户端接收',a.clientReceived?'已收到（模拟）':'等待接收证据'],['客户端上传',a.platformReceived?'已上传':r.status==='上传失败'?'上传失败':r.step===3?'上传中':'尚未完成'],['平台接收与状态更新',a.platformReceived?'已收到并关联请求（模拟）':'等待日志'],['回捞结果',a.platformReceived?'成功':a.retrievalStatus]].map(([name,status])=>`<li><strong>${name}</strong><span>${esc(status)}</span></li>`).join('')}</ol><details><summary>查看推送参数与协议边界</summary><p>本地关联号：${esc(a.requestId)}；模拟通道回执：${esc(a.channelReceipt||'无')}</p><p>来源：${esc(a.inputSource)}。绑定状态${a.bindingConfirmed?'由操作人确认，未查询阿里云':'未查询'}。</p><p>${esc(a.messageProtocol)}。通知扩展参数未配置，包名不代替阿里云服务端应用配置。</p></details><div class="toolbar">${!ended?btn(a.platformReceived?'模拟解析结果':r.step===1?'模拟客户端收到消息':r.step===2?'模拟客户端上传日志':'模拟平台收到日志',`advanceInlineCollection('${x.key}')`,'primary'):''}${!ended?btn('取消请求',`cancelInlineCollection('${x.key}')`):''}${ended&&!['完成','已取消','解析失败'].includes(r.status)?btn('重新发起回捞（模拟）',`retryInlineCollection('${x.key}')`):''}${recovered?btn('阅读重新解析结果',`aliOpenRecovered('${r.id}')`,'primary'):''}${r.task?btn('阅读返回日志',`openSourceLogs('${x.key}')`,'primary'):''}${a.platformReceived&&!r.task&&['解析失败','已取消'].includes(r.status)?btn('重新解析原文件',`collectionReparse('${r.id}')`,'primary'):''}${btn('导出处理记录',`exportParseRecord('${x.key}')`)}</div></section><section class="product-card"><h3>返回日志与调查</h3><p>已接收 ${a.platformReceived?r.files.length:0} 份文件；原解析可读 ${r.files.filter(f=>f.status==='可查').length} 份。${recovered?'重新解析批次已有 '+recovered.run.records.length+' 条可读事件。':''}日志中的设备与构建以客户端文件为准，账号或别名不能充当设备身份。</p><p>此处返回内容为合成演练样例，实际设备身份与构建未验证。</p>${r.issueId?btn('返回关联调查',`deskOpenIssue('${r.issueId}')`):btn('关联工单或建立问题',`collectionAssociateForm('${r.id}')`)}</section><details class="panel"><summary>完整处理记录</summary>${r.events.map(e=>`<p>${esc(e.time)} · ${esc(e.text)}</p>`).join('')}</details>`;};
const aliPreviousRetry=retryInlineCollection;
retryInlineCollection=function(key){const x=collectionByKey(key),r=x?.request,a=r?.product?.aliyun;if(!a)return aliPreviousRetry(key);try{const next=AR.create(state,{app:a.app.packageName,targetType:a.targetType,targetValue:a.targetValue,bindingConfirmed:a.bindingConfirmed,issueId:r.issueId,title:r.product.title,begin:r.begin,end:r.end,source:'重试 '+r.id,scenario:'success'},M);next.parent=r.id;M.advance(next);workUI.collectionKey=next.product.stableKey;workUI.collectionMode='push';save();render();}catch(e){toast(e.message);}};
const aliPreviousExport=exportParseRecord;
exportParseRecord=function(key){const r=collectionByKey(key)?.request;if(!r?.product?.aliyun)return aliPreviousExport(key);file(r.id+'-aliyun-retrieval.json',JSON.stringify({id:r.id,parent:r.parent,issueId:r.issueId,aliyun:r.product.aliyun,investigationWindow:{begin:r.begin,end:r.end},status:r.status,files:r.files,events:r.events},null,2));};
const aliPreviousView=views.collectioncenter;
views.collectioncenter=function(){return aliPreviousView().replace('通过推送下发回捞指令，等待客户端响应、日志上传和解析。可独立发起，也可关联工单继续调查。','从工单或手动输入取得阿里云推送参数，触发客户端上传日志。平台收到并更新状态后，回捞成功。').replace('回捞：取回设备或 Web 会话中已记录的日志。上传：导入手头已有文件并解析。调查中的证据缺口，可在问题工作台发起补充采集。','回捞：通过阿里云推送触发客户端上传。上传文件：导入已有日志。补充回捞：从工单继续发起。').replace('回捞设备日志','发起日志回捞');};
const aliPreviousMaterialSummary=collectionMaterialSummary;
collectionMaterialSummary=function(r){if(!r.product?.aliyun)return aliPreviousMaterialSummary(r);const c=C.coverage(r);return `<section class="product-card"><h3>返回材料</h3><p>回捞：${esc(r.product.aliyun.retrievalStatus)} · 解析：${r.task?'完成':r.status==='解析失败'?'失败':'未完成'}</p><p>观察到 ${c.count} 条合成事件。${c.begin?captureTime(c.begin)+' — '+captureTime(c.end):'等待可读日志'}</p><p>故障线索时段：${r.begin?captureTime(r.begin)+' — '+captureTime(r.end):'未填写'}；未将该时段映射成尚未确认的推送协议。</p><p>设备身份及构建未验证；本地合成样例不证明所填目标的真实现场，也不证明连续覆盖。</p></section>`;};
const aliPreviousScope=deskScope;
deskScope=function(x){if(!x?.asset?.identityUnknown)return aliPreviousScope(x);return `<section class="desk-scope"><div><strong>日志身份待确认</strong><p>版本 / 构建：未知。工单信息仅作排查线索，不填入日志元数据。</p><p>文件声明范围：${x.asset.begin?captureTime(x.asset.begin)+' — '+captureTime(x.asset.end):'未提供'}</p></div>${btn('返回关联调查',`deskOpenIssue('${x.issue.id}')`)}</section>`;};
const aliPreviousEvidenceMetadata=evidenceMetadata;
evidenceMetadata=function(t,row){const result=aliPreviousEvidenceMetadata(t,row);if(t&&(findAsset(t.assetId)?.identityUnknown||issue().requests.some(r=>r.task===t.id&&r.product?.aliyun)))return {...result,device:null,version:null,build:null,versionOrigin:'unknown',sourceVerified:false};return result;};
const aliPreviousAssetParse=assetParseView;
assetParseView=function(x){let html=aliPreviousAssetParse(x);if(x.asset?.identityUnknown)html='<div class="notice">返回文件未声明已验证的设备、版本或构建。可以解析与阅读，不能借用工单版本确认源码。</div>'+html.replace(' ·  / ',' · 版本未知 / 构建未知').replace('声明范围（北京时间）： —','声明范围：未提供');return html;};
const aliPreviousRail=collectionRail;
collectionRail=function(all,x){let html=aliPreviousRail(all,x);for(const entry of all){const r=entry.request,a=r.product?.aliyun;if(!a)continue;const title=`<b>${r.id} · ${esc(r.product.title)}</b>`;html=html.replace(title+badge(r.status,r.task?'ok':'warn'),title+badge(r.status==='已取消'&&!a.platformReceived?'已取消':a.retrievalStatus,a.platformReceived?'ok':'warn')+`<small>处理状态：${esc(r.status)}</small>`);}return html;};
function aliRecovered(r){const assets=r.issueId?(state.issues.find(i=>i.id===r.issueId)?.logAssets||[]).filter(a=>a.sourceKey===r.product.stableKey):(r.product.assets||[]);return assets.flatMap(a=>a.runs.filter(run=>run.task).map(run=>({a,run}))).at(-1);}
function aliOpenRecovered(id){const r=C.find(state,id),result=aliRecovered(r);if(!result)return toast('尚无可读解析批次');if(r.issueId)return selectAssetRun(result.a,result.run);openModal('独立解析结果',collectionParseHistory(r)+btn('关联并继续调查',`closeModal();collectionAssociateForm('${id}')`));}
render();
